cd /workspace; echo "=====MODEL_IDS decl"; grep -n "declare -A" pr/head/.claude/scripts/generated-model-maps.sh; echo "=====call_model model_override"; grep -n "model_override" pr/head/.claude/scripts/flatline-orchestrator.sh | head -20; echo "=====estimate_token_count callers"; grep -rn "estimate_token_count" pr/head/.claude/scripts/ | grep -v "^.*:#"; echo "=====yaml drift"; python3 -I - <<'EOF'
import sys
try:
    import yaml
except ImportError:
    print("no yaml module"); sys.exit(0)
d = yaml.safe_load(open("pr/head/.claude/defaults/model-config.yaml"))
decl = {}
for p, pv in (d.get("providers") or {}).items():
    for m, mv in (pv.get("models") or {}).items():
        if isinstance(mv, dict) and isinstance(mv.get("max_output_tokens"), int):
            decl[m] = mv["max_output_tokens"]
import re
gen = {}
txt = open("pr/head/.claude/scripts/generated-model-maps.sh").read()
blk = txt.split("declare -A MODEL_MAX_OUTPUT=(")[1].split(")")[0]
for k, v in re.findall(r'\["([^"]+)"\]="(\d+)"', blk):
    gen[k] = int(v)
print("catalog:", sorted(decl.items()))
print("generated:", sorted(gen.items()))
print("missing from generated:", {k: v for k, v in decl.items() if k not in gen})
print("extra in generated:", {k: v for k, v in gen.items() if k not in decl})
print("mismatch:", {k: (decl[k], gen[k]) for k in decl if k in gen and decl[k] != gen[k]})
# also check which entries have effective_input_ceiling but not probed_ceiling, and context windows
for p, pv in (d.get("providers") or {}).items():
    for m, mv in (pv.get("models") or {}).items():
        if isinstance(mv, dict) and "effective_input_ceiling" in mv:
            print(p, m, "cw=", mv.get("context_window"), "eff=", mv.get("effective_input_ceiling"), "probed=", mv.get("probed_ceiling"), "maxout=", mv.get("max_output_tokens"), "beta=", (mv.get("params") or {}).get("beta_headers"), "lc=", (mv.get("pricing") or {}).get("long_context"))
print("aliases:", d.get("aliases"))
EOF

